// ─── File: src/test/java/com/bank/hazards/HazardsComparisonTest.java ───
package com.bank.hazards;

import org.junit.jupiter.api.Test;
import java.lang.management.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class HazardsComparisonTest {

    // ═══ DEADLOCK detection ═══
    @Test
    void deadlock_detectedByThreadMXBean() throws InterruptedException {
        Object lockA = new Object(), lockB = new Object();

        Thread t1 = new Thread(() -> {
            synchronized (lockA) { try { Thread.sleep(50); } catch (InterruptedException e) {} synchronized (lockB) {} }
        });
        Thread t2 = new Thread(() -> {
            synchronized (lockB) { try { Thread.sleep(50); } catch (InterruptedException e) {} synchronized (lockA) {} }
        });
        t1.start(); t2.start();
        Thread.sleep(200);

        ThreadMXBean tmx = ManagementFactory.getThreadMXBean();
        long[] deadlocked = tmx.findDeadlockedThreads();
        if (deadlocked != null) {
            System.out.println("DEADLOCK detected! Threads: " + deadlocked.length);
            assertThat(deadlocked.length).isEqualTo(2);
        }
        t1.interrupt(); t2.interrupt();
    }

    // ═══ LIVELOCK: running but no progress ═══
    @Test
    void livelock_runningNoProgress() throws InterruptedException {
        ReentrantLock lockA = new ReentrantLock();
        ReentrantLock lockB = new ReentrantLock();
        AtomicInteger progress = new AtomicInteger(0);
        AtomicBoolean stop = new AtomicBoolean(false);

        Thread t1 = new Thread(() -> {
            while (!stop.get()) {
                lockA.lock();
                    if (!lockB.tryLock()) { lockA.unlock();
                    continue; }  // release + retry!
                try { progress.incrementAndGet(); break; }
                finally { lockB.unlock(); lockA.unlock(); }
            }
        });
        Thread t2 = new Thread(() -> {
            while (!stop.get()) {
                lockB.lock();
                    if (!lockA.tryLock()) { lockB.unlock();
                    continue; }  // release + retry!
                try { progress.incrementAndGet(); break; }
                finally { lockA.unlock(); lockB.unlock(); }
            }
        });

        t1.start(); t2.start();
        Thread.sleep(500);  // let them "livelock" briefly

        stop.set(true);
        t1.join(2000); t2.join(2000);
        System.out.println("Progress: " + progress.get());
        // Might be 0 or low — both kept acquiring/releasing without making progress!
    }

    // ═══ STARVATION: unfair lock, one thread waits forever ═══
    @Test
    void starvation_unfairLock() throws InterruptedException {
        ReentrantLock unfair = new ReentrantLock(false);  // non-fair!
        AtomicInteger longWaiterServed = new AtomicInteger(0);
        CountDownLatch started = new CountDownLatch(1);

        // Long waiter: tries to acquire lock
        Thread longWaiter = new Thread(() -> {
            started.countDown();
            unfair.lock();
            try { longWaiterServed.incrementAndGet(); }
            finally { unfair.unlock(); }
        });

        // Barge threads: keep acquiring and releasing rapidly
        unfair.lock();  // hold lock initially
        longWaiter.start();
        started.await();
        Thread.sleep(50);  // long waiter is now WAITING for lock

        // Release and immediately re-acquire (barging!)
        for (int i = 0; i < 100; i++) {
            unfair.unlock();
            unfair.lock();  // may barge ahead of longWaiter!
        }
        unfair.unlock();

        longWaiter.join(5000);
        // longWaiter may have waited through 100 barge cycles!
        assertThat(longWaiterServed.get()).isEqualTo(1);  // eventually served
    }

    // ═══ NO starvation with fair lock ═══
    @Test
    void noStarvation_fairLock() throws InterruptedException {
        ReentrantLock fair = new ReentrantLock(true);  // FAIR! FIFO!
        // Longest-waiting thread always gets the lock next!
        // No barging! No starvation!
        fair.lock();
        fair.unlock();
        assertThat(fair.isFair()).isTrue();
    }
}
